const input = $input.first().json;
const isVideo = input.media_type === 'video';
let vector, dim, model_id;
if (isVideo) {
  // Marengo async: task_id returned, polling needed. This is a placeholder.
  // In production: poll GET /v1.3/embed/{task_id} until status='ready', then read video_embedding.float
  vector = null; dim = 512; model_id = 'marengo-3';
} else {
  const data = input.data?.[0]?.embedding;
  vector = data || null; dim = 1024; model_id = 'voyage-multimodal-3';
}
return [{ json: { vector, dim, model_id } }];
